	'invoice_round_trip' => 'عودة رقم الفاتورة',
	'invoice_round_trip_help' => 'يحمل كل طلب نرسله رقم فاتورة خاصًا بنا. وإذا ضاع الرد يومًا، نعثر على الطلب من جديد بالبحث عن هذا الرقم في قائمة طلبات المزوّد. التحقق من ربط الحقول يثبت فقط أن القائمة تحتوي على هذا الحقل (وهو فارغ في معظم الطلبات القديمة)، ولا يثبت أن الرقم الذي نرسله يعود إلينا. وإلى أن يسجّل المدير الرئيسي مع الدليل أنه يعود، لا يُرسل أي طلب فعلي إلى تورود. التجارب (التشغيل التجريبي) غير متأثرة.',
	'invoice_round_trip_withdraw_confirm' => 'هل تريد سحب التأكيد؟ ستُحجز الطلبات الفعلية إلى أن يُسجَّل من جديد.',
	'withdraw_confirmation' => 'سحب التأكيد',
	'invoice_round_trip_unconfirmed_notice' => 'غير مؤكَّد. تُحجز الطلبات الفعلية إلى تورود إلى أن يتم التأكيد.',
	'invoice_round_trip_evidence' => 'الدليل',
	'invoice_round_trip_evidence_help' => 'اذكر كيف تأكدت: مثلًا الرد المكتوب من المزوّد عن واجهة إضافة الطلب (من ومتى)، أو طلب تجريبي أُنشئ عبر واجهة إضافة الطلب (وليس بكتابته في لوحة المزوّد) وقُرئ من جديد (رقمه ورقم الفاتورة الذي عاد وموضعه في القائمة: يقرأ البحث أول 150 طلبًا فقط). من 10 إلى 500 حرف. لا تلصق بيانات عملاء أو بيانات اعتماد: يظهر النص لكل مسؤول يفتح هذه الصفحة ويُحفظ في سجل التدقيق.',
	'invoice_round_trip_statement' => 'أؤكد أن رقم الفاتورة المُرسل مع الطلب يعود دون تغيير في قائمة طلبات المزوّد، في هذا المسار:',
