	'stock_field_path_not_set' => 'حدّد مسار المخزون في ربط حقول المنتجات أولًا؛ لا يمكن تأكيد شيء قبل ذلك.',
	'stock_is_set_by_the_warehouse_sync' => 'مخزون هذا المنتج يحدده تزامن المستودع؛ لن يُحفظ رقم يُكتب يدويًا.',
	'stock_controlled_by_warehouse_notice' => 'مخزون هذا المنتج يأتي من مستودع تورود. ما دام تزامن المستودع يعمل، لا تُحفظ أرقام المخزون المكتوبة في هذا النموذج.',
	'i_confirm_the_stock_field_is_available_to_sell' => 'أؤكد أن هذا الحقل في قائمة المنتجات هو الكمية المتاحة للبيع، بعد استبعاد الوحدات الموجودة في طلبات قبلها المستودع:',
	'torod_stock_confirmation_help' => 'لا تذكر الوثائق أي كمية تعيدها قائمة المنتجات، والمستودع يعرض عدة كميات (المتوفرة فعليًا، القابلة للبيع، المحجوزة، المخصصة). أكّد فقط الكمية التي صرّح المزوّد بأنها متاحة للبيع. إلى أن تفعل ذلك لا يُستخدم مخزون المستودع ويبقى المتجر على مخزونه الخاص.',
	'hold_live_submission_unproven' => 'ينتظر الطلب الفعلي خطوة تأكيد المزوّد: في تورود، يجب أن يسجّل المدير الرئيسي في صفحة تورود أن رقم الفاتورة يعود.',
